// Cleanup only IDs generated by the calling isolated respondent test.
const assert = require('node:assert/strict'), { createHash } = require('node:crypto');
const { cloudEnabled, readRecord, listRecords, removeRecord } = require('../lib/records.ts');
exports.cleanupLocalPlayerFixtures = async function(ids, owner, base) {
  assert.match(base, /^http:\/\/127\.0\.0\.1:\d+$/);
  assert.ok(process.env.HEYQUIZ_DATA_DIR && !cloudEnabled(), 'Synthetic local storage required');
  for (const id of ids) {
    const row = await readRecord('forms', id);
    if (row) assert.equal(row.owner_id, 'local');
    const removed = await owner.request.delete(base + '/api/forms/' + id, { headers: { Origin: base } });
    assert.ok([200, 404].includes(removed.status()));
    for (const kind of ['attempts', 'submissions', 'landing_visits']) {
      for (const row of await listRecords(kind, 'local')) if ((row.payload?.formId || row.payload?.form?.id) === id) {
        assert.equal(row.owner_id, 'local'); await removeRecord(kind, row.id, 'local');
      }
    }
    const receiptId = createHash('sha256').update(JSON.stringify(['local', id])).digest('hex');
    const receipt = await readRecord('result_report_revocations', receiptId);
    if (receipt) {
      assert.equal(receipt.owner_id, 'local'); assert.deepEqual(Object.keys(receipt.payload), ['retiredAt']);
      assert.equal(await readRecord('forms', id), null); assert.equal(await readRecord('published', id), null);
      await removeRecord('result_report_revocations', receiptId, 'local');
    }
  }
};
